# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe TimekeepingContract::FakeTimekeeping do
  let(:company) { create(:company) }
  let(:admin) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:fake) { described_class.new(token_public_key: timekeeping_key_pair.public_key) }

  before do
    create(:employment, company:, user: admin)
    admin.add_role :admin, company
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
  end

  # Acceptance: "Policies authorize the returned record."
  # An entry that changes after the monolith authorized it must not be deleted under that stale authorization.
  it "refuses a delete whose If-Match names a version the entry has moved past and keeps the entry" do
    entry = fake.add_entry(company_id: company.id, user_id: admin.id, project_id: project.id, work_date: Date.current.iso8601)
    token = with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      Timekeeping::UserToken.mint(user: admin, company:)
    end

    response = fake.call("DELETE", "/v1/companies/#{company.id}/entries/#{entry.fetch("id")}", headers: {
      "Authorization" => "Bearer #{token}", "Ownership-Generation" => fake.generation.to_s,
      "Idempotency-Key" => SecureRandom.uuid, "If-Match" => (entry.fetch("version") + 5).to_s
    })

    expect(response.status).to eq(409)
    expect(response.body["reason"]).to eq("version_conflict")
    expect(fake.stored_entry(entry.fetch("id"))["discarded_at"]).to be_nil
  end
end
